<div class="modal-backdrop" x-show="modal" x-cloak x-transition.opacity.duration.150ms @click.self="closeModal()"><section class="modal-panel" x-show="modal" x-transition.opacity.scale.95.duration.150ms x-ref="modalPanel" @keydown.tab="trap($event)" role="dialog" aria-modal="true" aria-labelledby="modal-title">
<header class="modal-heading"><div><span class="modal-kicker" x-text="modal==='task'?'یک قدم در مسیر هدف':'فضای کار راستا'"></span><h2 id="modal-title" x-text="({task:taskForm.id?'ویرایش تسک':'تسک جدید',project:'یک پروژه تازه',stage:stageId?'ویرایش مرحله':'مرحله جدید',label:labelForm.id?'ویرایش برچسب':'برچسب جدید',goal:'هدف پروژه',member:'افزودن هم‌تیمی'})[modal]"></h2></div><button class="icon-btn" @click="closeModal()" aria-label="بستن فرم" x-html="$icon('X')"></button></header>
<template x-if="modal==='task'"><form class="task-composer" @submit.prevent="saveTask()"><div class="task-composer-body"><div class="task-composer-topbar"><div class="task-context-control"><span x-html="$icon('FolderClosed')"></span><select x-model.number="taskForm.project_id" :disabled="!!taskForm.id" @change="projectChanged()" aria-label="پروژه تسک"><template x-for="p in projects" :key="p.id"><option :value="p.id" x-text="p.name"></option></template></select></div><button type="button" class="icon-btn" @click="closeModal()" aria-label="بستن فرم" x-html="$icon('X')"></button></div><fieldset :disabled="busy||!canWrite(formProject)">
<label class="task-title-input"><input x-model="taskForm.title" placeholder="نام تسک" required maxlength="200" aria-label="عنوان تسک"><small class="field-error" x-text="err('title')"></small></label>
<label class="task-description"><textarea x-model="taskForm.description" placeholder="توضیحات" rows="2" maxlength="10000" aria-label="توضیحات تسک"></textarea><small class="field-error" x-text="err('description')"></small></label>
<div class="task-meta-toolbar"><label class="meta-chip"><span x-html="$icon('LayoutGrid')"></span><select aria-label="مرحله من" x-model.number="taskForm.member_stage_id" @change="memberStageChanged()" required><option value="" disabled>مرحله من</option><template x-for="s in formMyStages" :key="s.id"><option :value="s.id" x-text="s.title"></option></template></select></label><label class="meta-chip"><span x-html="$icon('Users')"></span><select required x-model.number="taskForm.owner_id" @change="ownerChanged()"><option value="">مسئول</option><template x-for="m in formProject?.members||[]" :key="m.id"><option :value="m.id" x-text="m.name"></option></template></select></label><div class="meta-chip date-chip"><span x-html="$icon('CalendarDays')"></span><x-date-picker model="taskForm.due_date" label="مهلت تسک" /></div><button type="button" class="meta-chip ghost-chip" @click="startInlineStage()"><span x-html="$icon('Plus')"></span>مرحله من</button></div>
<div class="product-stage-line" x-show="selectedProductStage"><span>مرحله محصول</span><strong x-text="selectedProductStage?.title"></strong></div><small class="field-error" x-text="err('member_stage_id')"></small><small class="field-error" x-text="err('owner_id')"></small>
<div class="inline-stage-prompt" x-show="!formMyStages.length&&!inlineStage"><div><strong>هنوز «مرحله من» ندارید</strong><p>یک مرحله شخصی بسازید تا این تسک در مسیر شما قرار بگیرد.</p></div><button type="button" class="button small-button" @click="startInlineStage()"><span x-html="$icon('Plus')"></span>ساخت مرحله من</button></div>
<div class="inline-form compact-inline-stage" x-show="inlineStage"><div class="inline-form-head"><strong>مرحله من جدید</strong><button type="button" class="icon-btn" @click="inlineStage=false" x-html="$icon('X')"></button></div><div class="inline-stage-grid"><label>مرحله محصول مادر<select x-model.number="inlineStageForm.product_stage_id" required><option value="">انتخاب مرحله محصول</option><template x-for="s in formProject?.stages||[]" :key="s.id"><option :value="s.id" x-text="s.title"></option></template></select></label><label>عنوان<input x-model="inlineStageForm.title" placeholder="مثلاً بررسی و اصلاح"></label></div><div class="button-row"><button type="button" class="button primary small-button" @click="createInlineStage()">ساخت و انتخاب</button></div></div>
<div class="composer-actions"><button type="button" class="composer-action" @click="addSubtask()"><span x-html="$icon('CheckCheck')"></span>زیرتسک</button><button type="button" class="composer-action" @click="$refs.labelsSection?.scrollIntoView({behavior:'smooth',block:'nearest'})"><span x-html="$icon('Tags')"></span>برچسب</button><button type="button" class="composer-action" @click="$refs.attachmentsSection?.scrollIntoView({behavior:'smooth',block:'nearest'})"><span x-html="$icon('Paperclip')"></span>پیوست</button><div class="composer-start-date"><span>شروع</span><x-date-picker model="taskForm.start_date" label="تاریخ شروع تسک" /></div></div>
<div class="subtasks-field composer-section" x-show="taskForm.subtasks.length"><div class="field-heading"><span x-html="$icon('CheckCheck')"></span><strong>زیرتسک‌ها</strong><span class="muted" x-text="fa(taskForm.subtasks.length)"></span></div><template x-for="(s,i) in taskForm.subtasks" :key="i"><div class="subtask-input" draggable="true" @dragstart="dragIndex=i" @dragover.prevent @drop.prevent="reorderSubtask(i)"><span class="drag-handle" x-html="$icon('GripVertical')"></span><input type="checkbox" x-model="s.completed"><input x-model="s.title" placeholder="عنوان زیرتسک" required maxlength="200"><button type="button" class="icon-btn" @click="taskForm.subtasks.splice(i,1)" x-html="$icon('X')"></button></div></template></div>
<div class="composer-section labels-field" x-ref="labelsSection"><div class="field-heading"><span x-html="$icon('Tags')"></span><strong>برچسب‌ها</strong></div><input class="label-search" x-model="labelQuery" placeholder="جست‌وجو یا ساخت برچسب"><div class="label-options"><template x-for="l in formLabels" :key="l.id"><label class="tag selectable" :style="`--tag-color:${l.color}`" :class="{'chosen':taskForm.labels.includes(l.id)}"><input type="checkbox" :value="l.id" x-model.number="taskForm.labels"><i></i><span x-text="l.name"></span></label></template><button type="button" class="text-button accent" x-show="labelQuery&&!formLabels.some(l=>l.name===labelQuery)" @click="quickLabel()"><span x-html="$icon('Plus')"></span><span x-text="'ساخت «'+labelQuery+'»'"></span></button></div></div>
<div class="composer-section related-members"><div class="field-heading"><span x-html="$icon('Users')"></span><strong>همراهان</strong></div><div class="member-options"><template x-for="m in formProject?.members||[]" :key="m.id"><label class="member-choice"><input type="checkbox" :value="m.id" x-model.number="taskForm.members"><span class="avatar tiny"><img x-show="m.avatar_url" :src="m.avatar_url" :alt="m.name"><span x-show="!m.avatar_url" :style="`background:${color(m.id)}`" x-text="initials(m.name)"></span></span><span x-text="m.name"></span></label></template></div></div>
<div class="composer-section attachments-field" x-ref="attachmentsSection"><div class="field-heading"><span x-html="$icon('Paperclip')"></span><strong>پیوست‌ها</strong></div><label class="upload-zone compact-upload" @dragover.prevent @drop.prevent="filesAdded($event.dataTransfer.files)"><input type="file" multiple accept=".pdf,.png,.jpg,.jpeg,.webp,.txt" @change="filesAdded($event.target.files);$event.target.value=''" class="sr-only"><span x-html="$icon('Upload')"></span><span>افزودن فایل</span><small>حداکثر ۵ مگابایت</small></label><template x-for="(f,i) in pendingFiles" :key="i"><div class="attachment-row"><span x-html="$icon('Paperclip')"></span><span x-text="f.name"></span><button type="button" class="icon-btn" @click="pendingFiles.splice(i,1)" x-html="$icon('X')"></button></div></template><template x-for="a in taskForm.attachments" :key="a.id"><div class="attachment-row"><span x-html="$icon('Paperclip')"></span><a :href="'/attachments/'+a.id" x-text="a.original_name"></a><button type="button" class="icon-btn" x-show="canWrite(formProject)&&a.member_id===user.id" @click="deleteAttachment(a)" x-html="$icon('Trash2')"></button></div></template></div>
<div class="composer-section comments-field" x-show="taskForm.id"><div class="field-heading"><span x-html="$icon('MessageCircle')"></span><strong>گفت‌وگو</strong></div><template x-for="c in taskForm.comments" :key="c.id"><div class="comment"><span class="avatar small"><img x-show="c.user?.avatar_url" :src="c.user?.avatar_url"><span x-show="!c.user?.avatar_url" :style="`background:${color(c.member_id)}`" x-text="initials(c.user?.name)"></span></span><div class="comment-content"><div><strong x-text="c.user?.name"></strong><small x-text="commentTime(c.created_at)"></small></div><p x-show="!c.editing" x-text="c.body"></p><div class="comment-edit" x-show="c.editing"><textarea x-model="c.editBody" rows="2"></textarea><div class="button-row"><button class="text-button accent" type="button" @click="editComment(c)">ذخیره</button><button class="text-button" type="button" @click="c.editing=false">لغو</button></div></div><div class="comment-actions" x-show="c.member_id===user.id&&canWrite(formProject)"><button type="button" @click="c.editing=true;c.editBody=c.body">ویرایش</button><button type="button" class="danger-text" @click="deleteComment(c)">حذف</button></div></div></div></template><div class="new-comment"><span class="avatar small"><img x-show="user.avatar_url" :src="user.avatar_url"><span x-show="!user.avatar_url" :style="`background:${color(user.id)}`" x-text="initials(user.name)"></span></span><textarea x-model="commentText" placeholder="نظر بنویسید..." rows="1" maxlength="5000"></textarea><button type="button" class="icon-btn accent" @click="addComment()" :disabled="busy||!commentText.trim()" x-html="$icon('ArrowUpLeft')"></button></div></div>
<div class="composer-section task-history" x-show="taskForm.id"><div class="field-heading"><span x-html="$icon('History')"></span><strong>تاریخچه</strong></div><template x-for="a in taskForm.activities||[]" :key="a.id"><div class="activity-row"><span class="activity-dot"></span><div><p x-text="activityText(a)"></p><small x-text="relativeTime(a.created_at)"></small></div></div></template></div>
</fieldset></div><footer class="task-composer-footer"><div class="task-footer-left"><button type="button" class="icon-btn danger-text" x-show="taskForm.id&&canWrite(formProject)" @click="removeTask()" x-html="$icon('Trash2')"></button><label class="complete-label" x-show="taskForm.id"><input type="checkbox" x-model="taskForm.completed" :disabled="!canWrite(formProject)">تکمیل شده</label></div><div class="button-row"><button type="button" class="button" @click="closeModal()">لغو</button><button type="submit" class="button primary" x-show="canWrite(formProject)" :disabled="busy||!taskForm.title?.trim()||!taskForm.member_stage_id||!canWrite(formProject)" x-text="busy?'در حال ذخیره...':taskForm.id?'ذخیره':'افزودن تسک'"></button></div></footer></form></template>
<template x-if="modal==='project'"><form @submit.prevent="projectStep<3?nextStep():saveProject()"><div class="wizard-steps"><template x-for="(title,i) in ['اطلاعات پروژه','هدف پروژه','مراحل مسیر']" :key="i"><div :class="{'current':projectStep===i+1,'done':projectStep>i+1}"><span x-text="projectStep>i+1?'✓':fa(i+1)"></span><strong x-text="title"></strong></div></template></div><div class="modal-body"><div x-show="projectStep===1"><div class="form-intro"><h3>چه چیزی می‌خواهید بسازید؟</h3><p>با یک نام و توضیح کوتاه، به پروژه‌تان هویت بدهید.</p></div><label>رنگ پروژه<input type="color" x-model="projectForm.color"></label><label>نام پروژه<input x-model="projectForm.name" placeholder="نام پروژه شما" maxlength="150"><small class="field-error" x-text="err('name')"></small></label><label>توضیح کوتاه<textarea x-model="projectForm.description" placeholder="این پروژه درباره چیست؟" rows="3"></textarea></label></div><div x-show="projectStep===2"><div class="helper-box"><span x-html="$icon('Target')"></span><p>ابتدا هدف پروژه را مشخص کنید. مراحل پروژه، مسیر رسیدن به این هدف خواهند بود.</p></div><label>عنوان هدف<input x-model="projectForm.goal.title" placeholder="می‌خواهیم به چه نتیجه‌ای برسیم؟"><small class="field-error" x-text="err('goal.title')"></small></label><label>توضیح هدف<textarea x-model="projectForm.goal.description" rows="2" placeholder="هدف را کمی بیشتر توضیح دهید..."></textarea></label><label>معیار موفقیت<textarea x-model="projectForm.goal.success_criterion" rows="2" placeholder="از کجا بفهمیم به هدف رسیده‌ایم؟"></textarea><small class="field-error" x-text="err('goal.success_criterion')"></small></label><div class="form-grid"><label>تاریخ شروع<x-date-picker model="projectForm.goal.start_date" /><small class="field-error" x-text="err('goal.start_date')"></small></label><label>تاریخ هدف<x-date-picker model="projectForm.goal.target_date" /><small class="field-error" x-text="err('goal.target_date')"></small></label></div></div><div x-show="projectStep===3"><div class="form-intro"><h3>مسیر رسیدن به هدف را بسازید</h3><p>مرحله‌ها را بکشید و به ترتیب دلخواه بچینید.</p></div><template x-for="(s,i) in projectForm.stages" :key="i"><div class="wizard-stage" draggable="true" @dragstart="dragIndex=i" @dragover.prevent @drop.prevent="dropWizard(i)"><div class="wizard-stage-title"><span x-html="$icon('GripVertical')"></span><span class="step-number" x-text="fa(i+1)"></span><input x-model="s.title" placeholder="نام مرحله"><button type="button" class="icon-btn" @click="moveWizard(i,-1)" aria-label="مرحله قبل" x-html="$icon('ChevronRight')"></button><button type="button" class="icon-btn" @click="projectForm.stages.splice(i,1)" aria-label="حذف مرحله" x-html="$icon('Trash2')"></button></div><input x-model="s.description" placeholder="توضیح کوتاه (اختیاری)"><div class="form-grid"><label>شروع<x-date-picker model="s.start_date" /></label><label>پایان<x-date-picker model="s.end_date" /></label></div><small class="field-error" x-text="Object.keys(errors).filter(k=>k.startsWith('stages.'+i+'.')).map(k=>err(k)).join(' ')"></small></div></template><button type="button" class="button full-width dashed" @click="projectForm.stages.push({title:'',description:'',start_date:projectForm.goal.start_date,end_date:projectForm.goal.target_date})"><span x-html="$icon('Plus')"></span>افزودن مرحله</button><small class="field-error" x-text="err('stages')"></small></div></div><footer class="modal-footer"><span class="muted" x-text="'مرحله '+fa(projectStep)+' از ۳'"></span><div class="button-row"><button type="button" class="button" @click="projectStep>1?projectStep--:closeModal()" x-text="projectStep>1?'قبلی':'انصراف'"></button><button class="button primary" type="submit" :disabled="busy" x-text="busy?'در حال ساخت...':projectStep===3?'ساخت پروژه':'ادامه'"></button></div></footer></form></template>
<template x-if="modal==='stage'"><form @submit.prevent="saveStage()"><div class="modal-body"><div class="helper-box" x-show="stageUser"><span x-html="$icon('Users')"></span><p x-text="'مسیر اختصاصی '+stageUser?.name"></p></div><label x-show="stageUser">زیرمجموعه مرحله محصول<select x-model.number="stageForm.product_stage_id" :required="!!stageUser"><option value="">انتخاب مرحله محصول</option><template x-for="s in stageProject?.stages||[]" :key="s.id"><option :value="s.id" x-text="s.title"></option></template></select><small class="field-error" x-text="err('product_stage_id')"></small></label><label>نام مرحله<input x-model="stageForm.title" required maxlength="120"><small class="field-error" x-text="err('title')"></small></label><label>توضیحات<textarea x-model="stageForm.description" rows="3"></textarea></label><div class="form-grid"><label>شروع<x-date-picker model="stageForm.start_date" /><small class="field-error" x-text="err('start_date')"></small></label><label>پایان<x-date-picker model="stageForm.end_date" /><small class="field-error" x-text="err('end_date')"></small></label></div></div><footer class="modal-footer"><button type="button" class="text-button danger-text" x-show="stageId&&canWrite(stageProject)" @click="deleteStage({...stageForm,id:stageId,project_id:stageProjectId},stageKind,stageUser)">حذف مرحله</button><div class="button-row"><button type="button" class="button" @click="closeModal()">انصراف</button><button type="submit" class="button primary" :disabled="busy||!canWrite(stageProject)">ذخیره مرحله</button></div></footer></form></template>
<template x-if="modal==='goal'"><form @submit.prevent="saveGoal()"><div class="modal-body"><label>عنوان هدف<input x-model="goalForm.title" required><small class="field-error" x-text="err('title')"></small></label><label>توضیح هدف<textarea x-model="goalForm.description" rows="3"></textarea></label><label>معیار موفقیت<textarea x-model="goalForm.success_criterion" required rows="3"></textarea><small class="field-error" x-text="err('success_criterion')"></small></label><div class="form-grid"><label>شروع<x-date-picker model="goalForm.start_date" /></label><label>پایان<x-date-picker model="goalForm.target_date" /><small class="field-error" x-text="err('end_date')"></small></label></div></div><footer class="modal-footer"><span></span><div class="button-row"><button type="button" class="button" @click="closeModal()">انصراف</button><button type="submit" class="button primary" :disabled="busy">ذخیره هدف</button></div></footer></form></template>
<template x-if="modal==='label'"><form @submit.prevent="saveLabel()"><div class="modal-body"><label>نام برچسب<input x-model="labelForm.name" required maxlength="60"><small class="field-error" x-text="err('name')"></small></label><label>رنگ<div class="color-picker"><input type="color" x-model="labelForm.color"><template x-for="c in ['#ed8555','#9274be','#568c7b','#527fa9','#bb6073','#9b864f']"><button type="button" :style="`background:${c}`" @click="labelForm.color=c" :aria-label="'انتخاب رنگ '+c" :class="{'chosen':labelForm.color===c}"></button></template></div></label><label>توضیحات (اختیاری)<textarea x-model="labelForm.description" rows="2"></textarea></label><label x-show="!labelForm.id">محدوده برچسب<select x-model.number="labelForm.project_id"><option :value="null">شخصی، در همه پروژه‌ها</option><template x-for="p in projects.filter(p=>canWrite(p))" :key="p.id"><option :value="p.id" x-text="p.name"></option></template></select></label></div><footer class="modal-footer"><span class="tag" :style="`--tag-color:${labelForm.color}`" x-text="labelForm.name||'پیش‌نمایش'"></span><div class="button-row"><button type="button" class="button" @click="closeModal()">انصراف</button><button type="submit" class="button primary" :disabled="busy">ذخیره برچسب</button></div></footer></form></template>
<template x-if="modal==='member'"><form @submit.prevent="saveMember()"><div class="modal-body"><label>انتخاب هم‌تیمی<select x-model.number="memberForm.member_id" required><option value="">انتخاب عضو</option><template x-for="m in members.filter(m=>!currentProject?.members.some(x=>x.id===m.id))" :key="m.id"><option :value="m.id" x-text="m.name"></option></template></select><small class="field-error" x-text="err('member_id')"></small></label><p class="muted">اعضا از بخش «شما کی هستید؟» پروفایل خود را می‌سازند.</p></div><footer class="modal-footer"><span></span><div class="button-row"><button type="button" class="button" @click="closeModal()">انصراف</button><button type="submit" class="button primary" :disabled="busy" x-text="busy?'در حال ذخیره...':'افزودن عضو'"></button></div></footer></form></template>
</section></div>